import type { StudyQuestion } from "./study";

export const scenarioQuestions2: Record<string, StudyQuestion[]> = {
  "databricks-context-engineer-associate": [
    { q: "An agent's answers degrade in quality as a conversation grows past 30 turns, even though the model's context window technically fits everything. What is the most likely cause?", o: ["The model has a hardware fault", "Context dilution: irrelevant/stale turns crowd out the most relevant information, reducing the model's effective attention to what matters now", "Longer conversations always improve accuracy", "The temperature setting is too low"], a: 1, e: "Even within a technically sufficient context window, stuffing in every prior turn dilutes relevance — the model must attend across more noise to find what matters, which is why context engineering favors summarizing/pruning stale turns over raw accumulation.", t: "Scenario · Medium" },
    { q: "A support agent needs to remember a customer's account tier and preferences across sessions spanning days, not just within one conversation.", o: ["Rely solely on the model's context window", "Implement persistent memory (e.g., a store keyed by user ID that's retrieved and injected into context at the start of each session)", "Ask the customer to repeat their preferences every time", "Increase the context window size only"], a: 1, e: "Cross-session persistence requires an external memory store (not just the transient context window), from which relevant facts are retrieved and re-injected into context at the start of a new session — a core context-engineering pattern distinct from in-conversation context.", t: "Scenario · Medium" },
    { q: "An agent has access to 40 different tools, and giving it all 40 tool definitions in every prompt increases cost and confuses tool selection. What technique addresses this?", o: ["Always include all 40 tools for completeness", "Dynamically select and include only the subset of tools relevant to the current task/intent (tool retrieval/filtering) before constructing the prompt", "Remove tool use entirely", "Increase the model size"], a: 1, e: "Dynamically retrieving/filtering to only the relevant tools for the current step (rather than always injecting the full tool catalog) reduces prompt bloat, cost, and the chance of the model picking the wrong tool.", t: "Scenario · Medium" },
    { q: "A grounded Q&A agent must clearly indicate to the user when it is answering from retrieved documents versus general knowledge, for trust and auditability.", o: ["This distinction isn't important for context engineering", "Structure the prompt so retrieved context is clearly delimited and instruct the model to cite/attribute claims to that context (or state when it's not grounded)", "Merge retrieved text and instructions into one undifferentiated block", "Only show citations if the user explicitly asks"], a: 1, e: "Clear delimiting of grounded context plus explicit prompt instructions to cite sources (or flag ungrounded answers) is a core context-engineering practice for building trustworthy, auditable grounded agents.", t: "Scenario · Medium" },
    { q: "An agent occasionally repeats the same failed tool call in a loop when a tool returns an error, wasting turns and tokens.", o: ["This cannot be prevented", "Include tool error results explicitly back in context with guidance/format for how to handle failures, and add a loop/retry limit in the agent's control logic", "Remove all error handling from the tool", "Silently drop failed tool calls from context"], a: 1, e: "Feeding tool errors back into context (so the model can adapt) combined with an explicit retry/loop limit in the orchestration logic prevents runaway repeated failures — a common agent reliability pattern.", t: "Scenario · Medium" },
    { q: "A multi-step agent workflow needs the output of step 2 (a structured JSON summary) to be reliably parseable as input to step 3's tool call, but the model sometimes adds extra prose around the JSON.", o: ["Accept the extra prose and try to parse anyway", "Constrain the model's output format explicitly (e.g., structured output/JSON mode, or a strict prompt template plus output validation with retry-on-parse-failure)", "Switch to a much larger model with no format constraints", "Ask the user to fix the output manually each time"], a: 1, e: "Reliable structured hand-offs between agent steps require constraining output format (structured/JSON output modes or strict schemas) and validating with retries on failure, rather than hoping free-form prose stays parseable.", t: "Scenario · Hard" },
    { q: "An agent's system prompt has grown to include dozens of edge-case instructions added over months, and now the model inconsistently follows core instructions. What context-engineering principle is being violated?", o: ["More instructions always improve reliability", "Instruction context should be kept minimal, prioritized, and well-organized (e.g., hierarchy, only the most relevant rules), since excessive/competing instructions degrade adherence to any single one", "The model needs to be retrained", "System prompts have no effect on behavior"], a: 1, e: "Bloated, poorly prioritized system prompts create competing signals that dilute adherence to any individual instruction — a key context-engineering lesson is to keep instruction context lean, hierarchical, and focused on what's actually needed for the current task.", t: "Scenario · Hard" },
    { q: "A RAG-based agent must decide, per user turn, whether retrieval is even needed (e.g., 'hello' vs. 'what's my account balance'), to avoid unnecessary latency and irrelevant context injection.", o: ["Always retrieve on every turn regardless of content", "Implement a routing/decision step (rule-based or model-based) that determines whether retrieval is necessary before injecting retrieved context", "Never retrieve, to keep things simple", "Retrieve only on the first turn of every conversation"], a: 1, e: "Conditional retrieval — deciding per-turn whether retrieval is warranted — avoids wasted latency/cost and prevents irrelevant retrieved context from diluting the prompt on turns that don't need it, such as greetings.", t: "Scenario · Hard" },
    { q: "An agent orchestrating multiple sub-agents (a planner, a researcher, a writer) must pass only the relevant distilled findings from the researcher to the writer, not the researcher's full raw scratch-work.", o: ["Pass the researcher's entire raw transcript unfiltered", "Have the researcher produce a condensed, structured summary as its output contract, and pass only that summary into the writer's context", "Skip the researcher step entirely", "Merge all sub-agents into a single prompt with no separation"], a: 1, e: "In multi-agent context engineering, each sub-agent should have a clear output contract (e.g., a condensed summary) so downstream agents receive curated, relevant context rather than being flooded with upstream raw reasoning/scratch-work.", t: "Scenario · Hard" },
    { q: "A team wants to reduce token cost for a long-running agent conversation without losing important earlier facts the user shared (like their name and a stated constraint).", o: ["Truncate the oldest turns with no regard for content", "Periodically summarize/compress older turns into a compact memory note, preserving key facts and constraints, while dropping redundant conversational filler", "Never summarize; keep the full transcript forever", "Increase the model's context window as the only fix"], a: 1, e: "Rolling summarization — compressing older turns into a compact fact/constraint memory while dropping filler — is the standard context-engineering technique for controlling token cost in long conversations without silently losing important stated facts.", t: "Scenario · Hard" },
    { q: "An agent designed to answer HR policy questions must never answer questions outside that domain (e.g., general coding help), even if a user tries to redirect it mid-conversation.", o: ["Trust the base model to naturally stay on topic with no guidance", "Set a clear scope boundary in the system prompt with explicit refusal instructions for out-of-scope requests, and consider a lightweight classifier/guardrail step to catch drift before it reaches generation", "Give the agent every possible tool so it can answer anything", "Remove the system prompt so the model behaves generically"], a: 1, e: "Keeping an agent within its intended domain requires explicit scope instructions and refusal guidance in context, often reinforced with a guardrail/classification step, rather than relying on the base model to infer topic boundaries unaided.", t: "Scenario · Medium" },
    { q: "A context window budget must be shared between a large system prompt, retrieved documents, and conversation history, and all three keep growing until requests fail validation.", o: ["Let the request fail and do nothing", "Establish an explicit token budget allocation across the three components (e.g., capping history via summarization, capping retrieved chunks via top-k/reranking, and trimming the system prompt to essentials) so the total reliably fits", "Only shrink the system prompt and leave the others unbounded", "Switch to a model with no context limit"], a: 1, e: "Managing a fixed context budget across competing needs (instructions, retrieved context, history) requires deliberately allocating and bounding each component — rather than letting any one grow unchecked until the whole request fails.", t: "Scenario · Medium" },
    { q: "An agent occasionally forgets an explicit constraint the user stated early in a long conversation (e.g., 'never suggest option X') by the time it reaches turn 25.", o: ["This is unavoidable and cannot be improved", "Pin critical, persistent constraints in a dedicated always-included context slot (e.g., a running 'active constraints' block) rather than relying on them staying salient buried in early turn history", "Ask the user to repeat the constraint every single turn", "Increase the model's temperature"], a: 1, e: "Important standing constraints should be promoted into a persistent, always-included context section (rather than left to be recalled from deep in turn history), since relevance/attention to older buried turns degrades as a conversation grows.", t: "Scenario · Medium" },
    { q: "A context-engineered agent for coding tasks must include relevant code snippets from a large repository, but including the whole repo in context is infeasible.", o: ["Include the entire repository regardless of size", "Retrieve only the most relevant files/functions (e.g., via embedding search or a dependency-aware selection) based on the current task, injecting just that targeted subset into context", "Include only the first file alphabetically", "Skip code context entirely and rely on the model's training knowledge"], a: 1, e: "Just as with document RAG, code context should be selectively retrieved (via semantic search or dependency analysis) to include only what's relevant to the current task, rather than attempting to fit an entire large repository into the context window.", t: "Scenario · Medium" },
    { q: "An agent's few-shot examples in the prompt were written months ago and no longer reflect the current desired output format after a product change, causing inconsistent outputs.", o: ["Few-shot examples never need updating once written", "Treat few-shot examples as part of the maintained context/prompt asset that must be reviewed and updated as requirements evolve, since stale examples actively mislead the model toward outdated behavior", "Remove the examples permanently with no replacement", "Increase the number of examples without checking their accuracy"], a: 1, e: "Few-shot examples are part of the prompt's context and directly shape output style/format; stale examples actively pull the model toward outdated behavior, so they must be actively maintained and updated alongside evolving requirements, not treated as write-once.", t: "Scenario · Hard" },
    { q: "A context-engineered pipeline retrieves documents in one language but the user query and desired response are in another language, and naive retrieval performs poorly.", o: ["Cross-lingual scenarios are impossible to support", "Consider a multilingual embedding model for retrieval (or translating the query/documents to a common language) so semantic similarity works correctly across languages, then generate the final response in the user's language", "Only support the document's original language", "Concatenate untranslated documents and hope the model figures it out"], a: 1, e: "Cross-lingual RAG typically requires multilingual embeddings (or a translation step) so that semantic similarity search works correctly across languages, with generation still producing the response in the user's preferred language.", t: "Scenario · Hard" },
    { q: "An agent's context includes a large tool-call result (e.g., a 5,000-row query result) that overwhelms the prompt and adds little value beyond a summary.", o: ["Always include the full raw tool output verbatim", "Post-process large tool outputs before injecting into context — summarizing, truncating to the most relevant rows, or extracting only the fields needed for the next step", "Refuse to use tools that can return large results", "Split the conversation into a new session for every tool call"], a: 1, e: "Raw tool outputs, especially large ones, should be distilled (summarized, truncated, or field-filtered) before being placed back into context, since dumping the full raw result wastes tokens and dilutes the signal the model actually needs for the next step.", t: "Scenario · Hard" },
    { q: "A context engineer must decide whether to store an agent's long-term memory as raw conversation transcripts or as structured, extracted facts (e.g., key-value preferences).", o: ["Raw transcripts are always superior for every use case", "Structured, extracted facts are generally more efficient and reliable to retrieve and inject into future context than raw transcripts, though some raw context may still be kept for rare deep-dive needs", "Long-term memory should never be persisted in any form", "Only images should be stored as memory, never text"], a: 1, e: "Structured fact extraction (e.g., preferences, key stated constraints) is typically more compact, reliable to retrieve, and cheaper to inject into future context than storing and re-processing full raw transcripts, which is why most production memory systems favor structured extraction.", t: "Scenario · Hard" },
    { q: "An agent orchestration framework must decide the order in which system instructions, retrieved context, and conversation history are placed in the prompt to maximize instruction-following reliability.", o: ["Order never affects model behavior", "Follow the framework/model's documented best-practice ordering (commonly: system instructions first, then relevant retrieved context, then conversation history, then the current user turn) since positioning affects how reliably instructions are followed relative to other content", "Always put the user's current message first", "Randomize the order on every request"], a: 1, e: "Prompt structure and ordering measurably affects instruction adherence; following the model provider's documented best-practice structure (instructions, then context, then history, then the current request) is a core context-engineering discipline rather than an arbitrary choice.", t: "Scenario · Hard" },
    { q: "A context-engineered agent occasionally receives a user request that requires information from two different tools (e.g., a calendar and a weather API) before it can respond usefully.", o: ["Only ever allow one tool call per turn regardless of need", "Allow the orchestration loop to make sequential (or parallel, where independent) tool calls within a turn, feeding each result back into context before producing the final response", "Ask the user to make two separate requests", "Guess the weather instead of calling the API"], a: 1, e: "Multi-step tool orchestration — calling multiple tools within a turn (sequentially or in parallel when independent) and incorporating each result into context before the final response — is a core agentic context-engineering pattern for requests that genuinely need more than one data source.", t: "Scenario · Medium" },
  ],
  "microsoft-pl-300": [
    { q: "A report needs a measure showing total sales for the current year only, dynamically, regardless of which year is selected via a slicer elsewhere in the report that shouldn't affect this specific card.", o: ["A calculated column filtering the year", "A DAX measure using CALCULATE with a filter override (e.g., ALL on the date table combined with a YEAR filter, or a variable holding the current year) so it ignores the external slicer for this visual", "A plain SUM with no CALCULATE", "Filtering the underlying Power Query table permanently"], a: 1, e: "CALCULATE lets you override or add filter context; combining it with ALL() (to remove existing filters) and an explicit year condition creates a measure whose result doesn't depend on external slicer selections, unlike a plain SUM.", t: "Scenario · Medium" },
    { q: "A star-schema fact table connects to two date-related columns (order date and ship date), but only order date is used for the report's main timeline slicer, and ship date needs separate filtering logic.", o: ["Create two active relationships to the same date table", "Create one active relationship (order date) and one inactive relationship (ship date), activating the inactive one inside specific measures via USERELATIONSHIP", "Duplicate the date table for no reason", "Merge both dates into one column"], a: 1, e: "A fact table can have only one active relationship to a given dimension table at a time; the second (ship date) relationship is created as inactive, and USERELATIONSHIP is used inside specific DAX measures to activate it only when needed.", t: "Scenario · Medium" },
    { q: "A Power Query step to remove duplicate rows works fine in Power BI Desktop but fails to refresh correctly in the Service due to a data source that can't be folded (a REST API), causing very slow refresh.", o: ["Query folding always works regardless of source", "Since this source doesn't support folding, minimize transformation steps and push filtering as early as possible in the query, or pre-aggregate at the source/API level, to reduce data volume processed by the engine", "Ignore performance since the Service can handle any load", "Switch entirely to DirectQuery to avoid the issue"], a: 1, e: "When a source doesn't support query folding (like most REST APIs), transformations run entirely in the Power Query engine locally; minimizing steps and filtering data as early/aggressively as possible reduces the volume processed and improves refresh performance.", t: "Scenario · Medium" },
    { q: "Two fact tables (Sales and Returns) both relate to a Product dimension, but a report needs to compare sales and returns by product on one visual, and a snowflaked design is causing ambiguous filter paths.", o: ["Directly relate Sales and Returns to each other", "Keep both fact tables related to the single shared Product dimension (star schema) and use measures from each fact table together on the visual, relying on the shared dimension for filtering", "Merge Sales and Returns into one table always", "Remove the Product dimension entirely"], a: 1, e: "The standard star-schema pattern is for multiple fact tables to share common dimension tables; visuals can then combine measures from different fact tables filtered consistently through the shared dimension, avoiding ambiguous many-to-many paths that a direct fact-to-fact relationship would create.", t: "Scenario · Medium" },
    { q: "A row-level security role should ensure a regional sales manager only sees rows for their own region, determined dynamically by the logged-in user rather than a hardcoded region name per role.", o: ["Create a separate static role per region", "Use a dynamic RLS pattern: a DAX filter expression on the security table using USERNAME() or USERPRINCIPALNAME() joined to a user-to-region mapping table", "Apply filtering only in the Power Query stage", "RLS cannot be made dynamic"], a: 1, e: "Dynamic row-level security uses USERNAME()/USERPRINCIPALNAME() in a DAX filter against a mapping table (user → region), so one role definition automatically restricts each logged-in user to their own region — avoiding one static role per region.", t: "Scenario · Medium" },
    { q: "A measure calculating year-over-year growth returns blank for the earliest year in the dataset, and stakeholders ask why.", o: ["This is a bug in DAX that must be reported", "There is no prior-year data to compare against for the first year (e.g., SAMEPERIODLASTYEAR/DATEADD returns no rows), so the calculation correctly has nothing to divide by/against", "Blank always means the measure is broken", "The date table is missing entirely"], a: 1, e: "Time-intelligence functions like SAMEPERIODLASTYEAR rely on there being a prior period in the date range; for the very first year in the data, no prior year exists, so the YoY calculation legitimately returns blank rather than indicating an error.", t: "Scenario · Hard" },
    { q: "A DAX measure using CALCULATE with FILTER(ALL(Sales), Sales[Amount] > 1000) is much slower than expected on a large fact table. What is a faster equivalent pattern?", o: ["There's no better alternative", "Use CALCULATE with a direct boolean filter argument, e.g. CALCULATE([Total], Sales[Amount] > 1000), which the engine can often optimize better than FILTER over ALL() on a large table", "Add more FILTER wrappers", "Switch the whole model to Import from DirectQuery"], a: 1, e: "Simple boolean filter arguments passed directly to CALCULATE can be optimized more efficiently by the engine than an explicit FILTER(ALL(table), condition) pattern, which forces a full table scan construction — a known DAX performance tuning technique.", t: "Scenario · Hard" },
    { q: "A model has a many-to-many relationship between Products and Promotions (a product can have many promotions, a promotion can cover many products), and a report needs correct aggregation across this relationship.", o: ["Avoid many-to-many relationships entirely; they're not supported", "Use a bridge table between Products and Promotions and set relationship cardinality/cross-filter direction appropriately (many-to-many relationships are supported directly in the model, or via a bridge table for clarity/performance)", "Merge Products and Promotions into a single table", "Use only calculated columns to fake the relationship"], a: 1, e: "Power BI supports many-to-many relationships natively, but a bridge table is often used for clarity and performance, with cross-filter direction set appropriately so aggregations across the M:N relationship behave correctly.", t: "Scenario · Hard" },
    { q: "A composite model mixes an Import-mode table with a DirectQuery table, and a specific visual using both is slow due to a cross-source relationship forcing query folding limitations.", o: ["Composite models never have performance considerations", "Consider setting the smaller/reference table's storage mode to Dual (both cached and queryable) so it can be used efficiently regardless of which mode is active in the query context", "Switch everything to DirectQuery", "Remove the relationship entirely"], a: 1, e: "In composite models, setting a shared dimension table to Dual storage mode lets the engine choose the most efficient mode (cached Import or live DirectQuery) depending on the query's fact table, which is the standard fix for cross-source relationship performance issues.", t: "Scenario · Hard" },
    { q: "A published report's dataset needs to refresh automatically every night, and stakeholders in the Service should be alerted if a KPI crosses a business threshold without opening the report.", o: ["Only manual refresh and manual review are possible", "Configure a scheduled refresh on the dataset in the Power BI Service, and set up a data-driven alert on the relevant visual/tile in a dashboard", "Rebuild the report daily by hand", "Use Power Query to email stakeholders directly"], a: 1, e: "The Power BI Service supports scheduled dataset refresh (via a gateway if needed for on-prem sources) plus data alerts configured on dashboard tiles that notify users automatically when a KPI crosses a defined threshold — no manual checking required.", t: "Scenario · Hard" },
    { q: "A visual should let executives drill from a yearly total down through quarter, month, and day without building four separate charts.", o: ["Build four separate visuals, one per level, manually linked", "Build a single visual using a date hierarchy (Year/Quarter/Month/Day) and enable drill-down, so users click through levels within the same visual", "Disable hierarchies and require a slicer per level", "Use four separate reports"], a: 1, e: "Power BI's built-in date hierarchy drill-down lets a single visual support navigating from year down to day by clicking through levels, avoiding the need to build and maintain separate visuals per granularity.", t: "Scenario · Medium" },
    { q: "A report needs a measure that shows the running (cumulative) total of sales through the current date in the filter context, updating correctly as users change the date slicer.", o: ["A plain SUM(Sales[Amount]) with no date logic", "A DAX measure using CALCULATE with a filter such as dates <= MAX(dates) over the date table, computing a running total dynamically", "A calculated column computed once at load time", "SUMX over the entire table regardless of filter"], a: 1, e: "A running total in DAX uses CALCULATE with a cumulative filter condition (dates less than or equal to the max date in context) against the date table, so the measure recalculates dynamically as the user changes the date filter context.", t: "Scenario · Medium" },
    { q: "A model's date table isn't marked as an official date table, and time-intelligence functions like TOTALYTD produce incorrect results.", o: ["Time-intelligence functions work regardless of date table marking", "Mark the table as a Date Table (with a proper contiguous date column) in model settings, since built-in time-intelligence functions require a valid marked date table to compute correctly", "Add more measures to compensate", "Switch to DirectQuery to fix it"], a: 1, e: "Power BI's time-intelligence DAX functions rely on a validly marked Date Table (contiguous, one row per day) to compute correctly; without this, functions like TOTALYTD, SAMEPERIODLASTYEAR, etc. can silently return incorrect results.", t: "Scenario · Medium" },
    { q: "A Power Query step to unpivot several monthly columns (Jan, Feb, Mar...) into rows for a proper tabular model is needed before it can be used well in visuals.", o: ["Keep the wide format and build 12 separate measures", "Use Power Query's Unpivot Columns transformation to convert the wide monthly columns into a long format with Month and Value columns", "Manually re-enter the data in a new shape", "Use DAX to reshape the table at report time"], a: 1, e: "Unpivot Columns in Power Query is the standard transformation to convert wide/cross-tab data (one column per month) into a proper long/tabular format (Month, Value), which is far more usable for slicing, filtering, and time-intelligence in the model.", t: "Scenario · Medium" },
    { q: "A calculated measure using DIVIDE for a ratio occasionally needs to return blank instead of an error or 0 when the denominator is zero, matching business expectations.", o: ["Use plain division with the / operator", "Use DIVIDE(numerator, denominator, alternateResult) with the alternate result set to BLANK() (its default), which safely handles zero/blank denominators", "Manually filter out all zero-denominator rows from the model", "Wrap the division in IFERROR only"], a: 1, e: "DIVIDE() is DAX's safe division function, gracefully handling division by zero or blank denominators by returning a specified alternate result (BLANK() by default) instead of throwing a division error like the raw / operator would.", t: "Scenario · Hard" },
    { q: "A Power BI report connected via DirectQuery to a large SQL Server table is slow because every slicer interaction issues a new query against the source with a complex generated SQL statement.", o: ["DirectQuery has no way to improve this", "Reduce model complexity feeding each visual, add appropriate indexes on the source table for the columns used in filters/joins, and consider aggregations (a smaller Import-mode aggregation table) to serve common queries faster", "Switch every table to calculated columns", "Disable all slicers"], a: 1, e: "DirectQuery performance depends heavily on the source database; adding indexes on filtered/joined columns and using Power BI's aggregation feature (a fast Import-mode summary table that transparently serves common queries) are standard mitigations for slow DirectQuery interactivity.", t: "Scenario · Hard" },
    { q: "A workspace administrator needs to ensure that only specific individuals can edit a published report and its dataset, while a broader group can only view it.", o: ["Give everyone Admin access for simplicity", "Assign workspace roles appropriately (Member/Contributor for editors, Viewer for read-only access) or use app permissions/audience management for broader, view-only distribution", "Share the .pbix file via email to everyone", "There's no way to separate edit and view access"], a: 1, e: "Power BI workspace roles (Admin/Member/Contributor/Viewer) control edit vs. view-only access, and Power BI Apps with audience management let you distribute view-only experiences broadly without granting workspace edit rights.", t: "Scenario · Hard" },
    { q: "A DAX measure works correctly in a matrix visual grouped by Category but returns unexpected totals in the grand total row.", o: ["Grand totals are always simple sums of the visible rows", "The measure likely needs context-aware logic (e.g., HASONEVALUE checks or explicit total handling) since a measure using row-context-dependent logic (like division or ranking) doesn't automatically sum correctly to a grand total across a different filter context", "This is a rendering bug that cannot be fixed", "Switch the visual to a table instead of a matrix"], a: 1, e: "Measures involving ratios, rankings, or other non-additive logic don't naturally roll up to a correct grand total, since the grand total row evaluates the same DAX expression in a different (broader) filter context; explicit handling (e.g., checking HASONEVALUE or redefining the total's logic) is often required.", t: "Scenario · Hard" },
    { q: "A finance model needs to prevent end users from modifying report visuals or layout while still letting them apply their own slicer selections and export data.", o: ["Give everyone edit access to the report", "Publish/share the report in Reading view or via an App (view-only distribution) and enable 'Personalize visuals' or export permissions as needed, without granting edit rights to the underlying report", "Lock the .pbix file with a password only", "Disable all interactivity entirely"], a: 1, e: "Distributing via a Power BI App or Reading-view sharing gives users interactive consumption (slicers, personalize visuals, export) without edit rights to the report's layout or visuals, which is the standard way to separate consumption from report authoring.", t: "Scenario · Hard" },
    { q: "A shared dataset in the Power BI Service is used by five different downstream reports built by different teams, and a breaking change (renaming a column) would silently break all of them.", o: ["Rename the column freely since Power BI handles this automatically", "Treat the shared dataset as a managed contract: communicate/version changes, use certified/promoted datasets with clear ownership, and coordinate breaking changes (like renames) with downstream report owners before applying them", "Delete and recreate the dataset from scratch for every change", "Let each downstream report team discover the break on their own"], a: 1, e: "A shared dataset used across multiple reports functions as a data contract; renaming or restructuring columns without coordinating with downstream report owners silently breaks their reports, so certified datasets, ownership, and change communication are the standard governance practice.", t: "Scenario · Medium" },
  ],
  "qlik-sense-data-architect": [
    { q: "A load script joins two tables that unexpectedly share two identically named fields you didn't intend to relate on, creating a synthetic key and inflating row counts downstream.", o: ["Ignore it; synthetic keys don't affect results", "Rename one of the unintentionally shared fields (using AS) in the LOAD statement so only the intended key remains common between the tables", "Delete one of the tables entirely", "Use CONCATENATE instead of LOAD"], a: 1, e: "Renaming the accidental extra shared field with AS in the LOAD script removes the unintended second common field, eliminating the synthetic key so the tables associate only on the field actually intended as the key.", t: "Scenario · Medium" },
    { q: "A nightly script currently reloads an entire multi-million-row fact table from the source database every run, which is becoming too slow as data grows.", o: ["Add more RAM only", "Implement incremental load: extract only new/changed rows (e.g., via a modified timestamp WHERE clause) each run, then concatenate with the existing QVD of historical data", "Switch to a full reload but at night only", "Remove the transaction log"], a: 1, e: "Incremental load is the standard Qlik pattern for large, growing fact tables: pull only new/changed rows from the source based on a watermark (like a modified date), then append them to the previously stored QVD, avoiding a full re-extract every run.", t: "Scenario · Medium" },
    { q: "Two tables in a data model form a circular reference after adding a new lookup table, causing Qlik to flag it and associations to behave unpredictably.", o: ["Circular references are harmless and can be left as-is", "Break the loop by renaming a field to remove one of the redundant associations, or restructure using a link table so there's a single unambiguous path between tables", "Add another table to the loop to balance it", "Use Section Access to hide the issue"], a: 1, e: "A circular reference must be resolved because Qlik cannot guarantee consistent association behavior otherwise; renaming a field to break the redundant link, or introducing a link table for a clean star-like structure, are the standard fixes.", t: "Scenario · Medium" },
    { q: "A load script needs to add a single 'Region' lookup value to a large fact table based on Store ID, without risking any row duplication.", o: ["JOIN on Store ID", "Use a mapping table with Mapping LOAD and ApplyMap() to add the Region value by lookup, since ApplyMap never duplicates rows", "CONCATENATE the region table to the fact table", "Load the region table twice"], a: 1, e: "ApplyMap performs a key-based lookup without altering the row count of the target table, unlike a JOIN which can multiply rows if the join key isn't unique on the joined side — making it the safer choice for adding a single lookup field.", t: "Scenario · Medium" },
    { q: "A QVD-based load script that used to run in seconds has slowed dramatically after someone added a WHERE clause filtering on a non-indexed transformed field during the QVD load.", o: ["QVD loads are always slow regardless of transformations", "The WHERE clause and transformation broke 'optimized' QVD load mode, forcing Qlik to read and process every row instead of streaming the file directly; move the filter to a resident load after an optimized load, or avoid transforming during the QVD read", "Delete the QVD and start over", "Add more fields to the SELECT"], a: 1, e: "Optimized QVD loads only apply when there are no transformations and no WHERE clause on non-indexed fields during the QVD LOAD statement itself; adding either breaks optimization and drops back to much slower row-by-row processing.", t: "Scenario · Hard" },
    { q: "A finance dataset must ensure that a regional controller can only see rows for their assigned cost centers, enforced at the data level regardless of what the app's UI allows selecting.", o: ["Rely on UI-level filters/bookmarks only", "Implement Section Access with a security table mapping usernames (or NTNAME) to allowed cost-center values, so reduction happens at data load time", "Hide the fields in the sheet only", "Give everyone full access and trust them"], a: 1, e: "Section Access is Qlik's row-level, data-layer security mechanism — reduction happens during data load based on the logged-in user's mapped access values, so it can't be bypassed by manipulating the UI, unlike sheet-level hiding or bookmarks.", t: "Scenario · Hard" },
    { q: "A star-schema model has multiple fact tables (Orders, Shipments) that both need to relate cleanly to a shared calendar and shared product dimension without creating ambiguous multi-fact associations.", o: ["Directly associate Orders and Shipments to each other on date and product", "Keep Orders and Shipments as separate fact tables, each associated to the shared Calendar and Product dimensions (classic star schema), avoiding a direct fact-to-fact link", "Merge Orders and Shipments into one table regardless of grain differences", "Remove the Calendar dimension"], a: 1, e: "The standard star-schema pattern keeps multiple fact tables independent, each linking to shared conformed dimensions (Calendar, Product); associating facts to each other directly, especially at different grains, creates ambiguous or incorrect associations.", t: "Scenario · Hard" },
    { q: "A load script builds a link table to resolve a data model with three fact tables sharing several dimensions, and now needs to ensure the link table's composite key is both unique and efficient.", o: ["Concatenate all dimension keys as text with no consideration for size", "Build a composite key (e.g., via AutoNumber() on a concatenation of the relevant dimension keys) in the link table load, keeping it as a single efficient key field", "Use multiple separate composite keys per fact", "Avoid AutoNumber and use raw string concatenation only, regardless of performance"], a: 1, e: "AutoNumber() converts a composite string key into a compact integer, which is both memory-efficient and fast for associations — the recommended technique when building link-table composite keys from concatenated dimension values.", t: "Scenario · Hard" },
    { q: "A data architect must ensure a scheduled reload doesn't silently continue if a critical source table returns zero rows (indicating a likely upstream failure), rather than publishing an app with missing data.", o: ["Let the reload finish silently regardless of row counts", "Add a script-level check (e.g., using NoOfRows()) after the load, and trigger an error/abort or alert if the row count is unexpectedly zero or below an expected threshold", "Manually check the app every morning", "Disable reloads entirely"], a: 1, e: "Adding explicit row-count validation (via NoOfRows()) with conditional logic to abort/alert on unexpected results is standard practice for guarding against silent upstream failures that would otherwise publish an app with missing or incomplete data.", t: "Scenario · Hard" },
    { q: "A QVD incremental-load script must handle deletions from the source (rows that existed yesterday but are gone today), which a simple 'append new rows' pattern would miss entirely.", o: ["Incremental loads cannot handle deletions at all", "Do a full extract of current keys from the source, compare against the QVD's keys, and remove (or flag) rows no longer present, in addition to inserting new/changed rows", "Ignore deletions since they rarely matter", "Reload the full history table every hour instead"], a: 1, e: "True incremental patterns that must reflect deletions require comparing the full set of current source keys against the stored QVD keys to identify removals, since a pure append-only incremental load has no way to detect rows that disappeared from the source.", t: "Scenario · Hard" },
    { q: "A load script needs to bring in only records modified since the last successful reload, using a 'ModifiedDate' column, and must avoid missing records modified during the reload window itself.", o: ["Filter strictly WHERE ModifiedDate > last_reload_time with no buffer", "Use a slightly overlapping window (e.g., WHERE ModifiedDate >= last_reload_time - buffer) combined with a dedup/replace step, to avoid missing records modified right at the boundary of the previous run", "Only reload once per week to avoid the issue", "Ignore the boundary condition since it's rare"], a: 1, e: "A strict greater-than filter risks missing rows modified in the same instant as the last extraction; a small overlapping buffer window combined with deduplication (keeping the latest version per key) is the standard defensive pattern for incremental extraction boundaries.", t: "Scenario · Medium" },
    { q: "A Qlik Sense app must connect to a REST API paginated in pages of 100 records, and the load script needs to loop until no more pages are returned.", o: ["A single LOAD statement with no looping logic", "Use a DO WHILE loop in the load script, incrementing the page parameter and issuing successive REST connector calls until an empty/short page indicates the end", "Manually specify every page number in advance", "This requires a third-party ETL tool"], a: 1, e: "Paginated REST APIs are handled in Qlik load scripts with a DO WHILE loop that increments the page/offset parameter and repeats the call until a stopping condition (like an empty result) is met — a common data-architect scripting pattern.", t: "Scenario · Medium" },
    { q: "A data architect needs to validate, immediately after loading a critical table, that a key field contains no NULLs before the rest of the script proceeds.", o: ["Trust the source data implicitly with no checks", "Add an inline validation using functions like IsNull() aggregated (e.g., counting nulls) and conditionally trigger an error/abort if any are found before continuing", "Only check for NULLs manually after publishing", "Remove the key field entirely if it might have nulls"], a: 1, e: "Defensive load-script validation (counting/checking for unexpected NULLs in a key field right after loading) lets the script fail fast before building a data model on top of bad data, rather than discovering the issue after publishing.", t: "Scenario · Medium" },
    { q: "Two source systems use different casing and whitespace for what should be the same customer name key, causing failed associations in the Qlik model.", o: ["Assume the associative engine will fix this automatically", "Standardize the key during load with functions like Upper()/Trim() (or a cleaner surrogate key) applied consistently to both sources before association", "Leave the data as-is and manually cross-reference", "Merge the two source systems' databases physically first"], a: 1, e: "Association in Qlik depends on exact field-value matches; cleaning/normalizing keys with Trim()/Upper() (or building a consistent surrogate key) during load resolves mismatches caused by casing or whitespace differences across source systems.", t: "Scenario · Medium" },
    { q: "A QVD file used by multiple apps must be regenerated by a single 'staging' script and then consumed identically by several downstream apps without each app re-extracting from the original source.", o: ["Each downstream app independently queries the original source", "Build a shared staging/ETL script that extracts from source and writes a QVD once, then have downstream apps do an optimized load from that shared QVD", "Copy-paste the extraction logic into every downstream app", "Combine all apps into a single monolithic app instead"], a: 1, e: "A shared staging layer (extract once to QVD, then multiple apps optimized-load from that QVD) is a core Qlik data-architecture pattern — it avoids redundant source extraction and ensures consistency across all consuming apps.", t: "Scenario · Hard" },
    { q: "A very large QVD load is unexpectedly not running in optimized mode even though the script has no WHERE clause or explicit transformation on the QVD LOAD line.", o: ["Optimized mode has no other requirements", "Check for hidden causes such as renaming fields with AS (which can break optimization in some cases), or an implicit type conversion; ensure the LOAD is a straightforward field list with matching names from the QVD", "This means the QVD file itself is corrupted", "Add more RAM as the only fix"], a: 1, e: "Beyond WHERE clauses, other subtle script constructs (like renaming fields or certain transformations even in the field list) can silently break optimized QVD load mode; a data architect needs to recognize these less obvious causes, not just the WHERE-clause case.", t: "Scenario · Hard" },
    { q: "A Section Access table needs to allow a specific 'admin' user to see all data (bypass reduction) while all other users are reduced to their own region.", o: ["Section Access cannot support an unrestricted admin exception", "Add a row in the Section Access table for the admin user with a wildcard value (e.g., '*') in the reduction field, which Qlik treats as matching all values for that field", "Duplicate the entire app without Section Access for the admin", "Grant the admin a separate login with no Section Access table at all"], a: 1, e: "Qlik's Section Access supports a wildcard ('*') in a reduction field to mean 'all values', so an admin's row can use '*' for the region field while other users have specific region values, achieving an unrestricted-admin exception within the same reduction table.", t: "Scenario · Hard" },
    { q: "A data architect must design a model where a single fact table needs to be sliced by both a standard calendar and a fiscal calendar (starting in a different month) without duplicating the fact table.", o: ["Duplicate the entire fact table twice, once per calendar", "Build both a standard Calendar dimension and a Fiscal Calendar dimension, each linked to the same date key on the fact table via separate links (or a canonical date dimension with fiscal attributes as extra fields)", "Only support one calendar type per app", "Convert all dates in the fact table to fiscal dates only"], a: 1, e: "The cleanest approach is a single date dimension carrying both standard and fiscal calendar attributes (or two calendar dimensions linked via the same date key), letting one fact table be sliced by either calendar without duplicating fact data.", t: "Scenario · Hard" },
    { q: "A newly onboarded data source delivers data in a different timezone than the rest of the model, causing daily aggregates to misalign by several hours near midnight boundaries.", o: ["Timezones never affect Qlik data models", "Convert the incoming timestamps to a consistent standard timezone during load (using appropriate date/time functions) before deriving date keys used for aggregation", "Ignore the offset since it only affects a few hours", "Force all other sources to change their timezone instead"], a: 1, e: "Timezone inconsistencies across sources should be normalized during load (converting to a single standard timezone before deriving the date key), otherwise daily/date-based aggregations near midnight will be misaligned between sources — a subtle but real data-architecture concern.", t: "Scenario · Hard" },
    { q: "A reload task chains two Qlik apps (App A produces a QVD that App B consumes), and B occasionally reads a stale QVD because the two tasks aren't explicitly coordinated in the scheduler.", o: ["Schedule both tasks independently at similar times and hope for the best", "Chain the tasks explicitly so B only triggers after A completes successfully (e.g., via the task scheduler's 'trigger on success of another task' option)", "Merge both apps into one to avoid the dependency", "Manually run B by hand after checking A finished"], a: 1, e: "Explicit task chaining (triggering a downstream reload only on successful completion of the upstream one) removes the timing guesswork of independently scheduled tasks and guarantees the downstream app always reads a freshly produced QVD.", t: "Scenario · Hard" },
  ],
  "qlik-sense-business-analyst": [
    { q: "A KPI object should show total sales only for the currently selected year, but recalculate correctly as users change other selections like region or product.", o: ["A hardcoded value pasted into a text box", "A measure expression like Sum(Sales) that responds naturally to the current selection state, since Qlik recalculates expressions based on all active selections", "A calculated column fixed at load time", "Sum(Sales) with no selections applied ever"], a: 1, e: "Qlik Sense expressions like Sum(Sales) are dynamically recalculated based on the current selection state across all fields, so as users change region/product/year selections the KPI updates automatically — no special logic is needed beyond a normal aggregation expression.", t: "Scenario · Medium" },
    { q: "An analyst needs a chart expression that always shows total company sales as a fixed reference line, ignoring whatever region or product the user has currently selected.", o: ["Sum(Sales) with no modification", "Sum({1} Sales), using the {1} set to ignore current selections and use the full dataset", "Sum({$} Sales)", "A calculated dimension"], a: 1, e: "The {1} set analysis operator represents the full data set disregarding any current selections, letting the expression compute a fixed 'all data' total (like a benchmark line) alongside selection-driven expressions in the same chart.", t: "Scenario · Medium" },
    { q: "A business analyst wants to compare 'this year' sales against 'last year' sales side-by-side in the same bar chart, without changing the user's actual field selections.", o: ["Ask users to manually toggle between two apps", "Use two separate measure expressions with set analysis, e.g. Sum({<Year={$(=Max(Year))}>} Sales) and Sum({<Year={$(=Max(Year)-1)}>} Sales)", "Only show one year at a time", "Create two separate sheets, one per year"], a: 1, e: "Set analysis with dynamic variables (like $(=Max(Year))) lets two independent measure expressions each pin to a specific year regardless of the user's actual field selections, enabling a clean side-by-side this-year vs last-year comparison in one visual.", t: "Scenario · Medium" },
    { q: "A user complains that after selecting a specific customer, the sales-by-region bar chart shows the region as gray/excluded even though it should still be selectable context.", o: ["This is expected and requires no action", "Explain Qlik's selection states: green (selected), white (possible), gray (excluded/alternative) — the region is grayed out because it has no association with the selected customer's data, which is the associative engine correctly reflecting the data relationships", "Force all fields to always stay green", "This indicates the app is broken"], a: 1, e: "Gray in Qlik Sense means excluded (no association exists between the current selections and that value) — this is the associative engine working correctly, showing the user exactly which values are and aren't connected to their current selection, not a bug.", t: "Scenario · Medium" },
    { q: "An analyst needs to group several individual product SKUs into a single 'Other' bucket in a bar chart to declutter a long tail of small-volume items.", o: ["Manually delete the small SKUs from the data", "Use a Qlik Sense group (a calculated dimension using a group, or an Aggr/If-based bucketing expression) to combine long-tail SKUs into an 'Other' category", "Sort the chart differently and hope it helps", "Filter out the small SKUs entirely from the app"], a: 1, e: "Grouping (via Qlik's grouping feature or a calculated dimension expression that buckets small values into 'Other') declutters a long-tail chart while still keeping the underlying data available for drill-down, rather than deleting or hiding it outright.", t: "Scenario · Hard" },
    { q: "A chart's set analysis expression Sum({<Year={2025}>} Sales) fails to update when the user changes the app's global 'as of' year via a variable, which was working before someone hardcoded the year.", o: ["Set analysis can never use variables", "Replace the hardcoded value with the variable, e.g. Sum({<Year={$(vSelectedYear)}>} Sales), so the set analysis dynamically reflects the variable's current value on each recalculation", "Delete the set analysis and use plain Sum(Sales)", "Change the variable into a dimension instead"], a: 1, e: "Set analysis expressions can and should reference variables using $(variableName) syntax for dynamic behavior; hardcoding a literal value (like {2025}) breaks that dynamism, so replacing it with the variable restores the intended behavior.", t: "Scenario · Hard" },
    { q: "A dashboard needs a measure showing the percentage each product contributes to its own category's total, recalculated correctly at whatever selection level the user is viewing.", o: ["Sum(Sales) divided by a hardcoded total", "Sum(Sales) / Aggr(Sum(Total <Category> Sales), Category) or equivalently Sum(Sales)/Sum(Total <Category> Sales), using Total qualified by the Category dimension to compute the category-level denominator dynamically", "A static percentage entered manually per product", "Sum(Sales) / Sum(Total Sales) without qualifying by Category"], a: 1, e: "Sum(Total <Category> Sales) computes the total sales for the product's category regardless of the chart's product-level dimensionality, giving a correct dynamic percent-of-category-total that respects current selections but not the chart's own row-level dimension — the standard 'percent of parent group' pattern.", t: "Scenario · Hard" },
    { q: "A business analyst needs a KPI showing the count of distinct customers who purchased in the current selection, not the count of order rows.", o: ["Count(Orders)", "Count(Distinct CustomerID)", "Sum(CustomerID)", "Count(CustomerID) without Distinct, since it's the same thing"], a: 1, e: "Count(Distinct CustomerID) counts unique customers rather than every order row, which is essential when a customer can have multiple orders — a plain Count(CustomerID) or Count(Orders) would overcount customers who ordered more than once.", t: "Scenario · Hard" },
    { q: "A visualization needs to rank and show only the top 5 customers by sales, but the ranking must update correctly as the user filters by region.", o: ["Hardcode the top 5 customer names", "Use dimension limits (e.g., 'Top 5 by expression: Sum(Sales)') on the Customer dimension in the chart, which Qlik recalculates dynamically per the current selection", "Manually sort and delete rows past 5 each time", "Filter to 5 arbitrary customers in the load script"], a: 1, e: "Qlik Sense chart dimension limits ('Top N by expression') dynamically recompute the top N values based on the live expression and current selection context, correctly re-ranking as the user changes filters like region — unlike a hardcoded or load-time approach.", t: "Scenario · Hard" },
    { q: "An analyst wants an alternate state so users can compare two independently selected sets of customers (Set A vs Set B) on the same chart, each with its own selections.", o: ["This requires two separate apps", "Define two alternate states in the app, assign selections to each state independently, and reference each state in the relevant measure expressions (e.g., Sum({StateA} Sales) vs Sum({StateB} Sales))", "Use two bookmarks and switch manually between them constantly", "Alternate states aren't supported in Qlik Sense"], a: 1, e: "Alternate states let different objects/expressions reference independently maintained selection contexts within the same app; assigning a state to each 'set' and referencing it by name in set analysis is exactly the mechanism for building side-by-side comparison visuals like this.", t: "Scenario · Hard" },
    { q: "An analyst needs a bookmark that captures the current selections so a specific view can be shared with a colleague and reopened later exactly as configured.", o: ["Take a screenshot instead", "Create a Bookmark, which stores the current selection state (and optionally the current sheet) so it can be reapplied later or shared with others", "Manually document which fields were selected in a text file", "Rebuild the selections from memory each time"], a: 1, e: "Bookmarks in Qlik Sense capture the exact selection state at a point in time, allowing a user to reapply it instantly later or share it with colleagues — the built-in mechanism for preserving and reusing specific analytical views.", t: "Scenario · Medium" },
    { q: "An analyst needs a measure that shows sales excluding a specific promotional category, without permanently filtering that category out of the whole app.", o: ["Permanently remove the category from the data model", "Use set analysis to exclude the category within the expression itself, e.g. Sum({<Category-={'Promo'}>} Sales), leaving the rest of the app's selections and data intact", "Ask users to manually deselect the category every time", "Build a separate app without the promo category"], a: 1, e: "Set analysis modifiers like Category-={'Promo'} exclude specific values from just that expression's calculation, without altering the underlying data model or requiring users to manage selections manually — ideal for a single measure-level exclusion.", t: "Scenario · Medium" },
    { q: "A chart needs to highlight, using color, whether each region's sales are above or below the company average, updating dynamically as selections change.", o: ["Hardcode fixed colors per region", "Use a color-by-expression / dimension coloring rule comparing each region's value to Avg(Total <Region> Sales) or the overall average, changing color dynamically based on that comparison", "Sort by color manually after each refresh", "Only use a single color for all regions"], a: 1, e: "Qlik's color-by-expression capability lets a chart's colors be driven by a dynamic condition (e.g., comparing a region's value to the live company average), so highlighting above/below-average performance updates automatically as selections change.", t: "Scenario · Medium" },
    { q: "A business analyst needs a single measure showing the difference between this period's sales and the prior period's sales (not the ratio), for a variance card.", o: ["Sum(Sales) alone", "Sum({<Period={$(=Max(Period))}>} Sales) - Sum({<Period={$(=Max(Period)-1)}>} Sales), computing the arithmetic difference between two set-analysis-scoped expressions", "Divide this period by last period", "A calculated dimension instead of a measure"], a: 1, e: "Subtracting two set-analysis-scoped expressions (this period vs. the prior period, each pinned via dynamic variables) gives the absolute variance needed for a difference-based KPI card, distinct from a ratio/percentage comparison.", t: "Scenario · Medium" },
    { q: "An analyst's straight table needs a subtotal row per region showing the sum of that region's products, in addition to individual product rows.", o: ["This requires a separate chart per region", "Enable subtotals in the table/pivot table's presentation settings (or use a pivot table with the Region dimension), which automatically computes and displays a subtotal row per region group", "Manually calculate and type in the subtotal for each region", "Use a KPI object instead of a table"], a: 1, e: "Qlik Sense pivot tables (and straight tables with subtotal options enabled) can automatically compute and display grouped subtotal rows per dimension value (like region), without manual calculation.", t: "Scenario · Medium" },
    { q: "A dashboard needs a measure that shows the number of days since a customer's last purchase, to flag customers at risk of churn.", o: ["Count(Orders)", "Today() - Max(OrderDate) computed per customer (e.g., in an Aggr or dimension-level expression), giving days since last purchase", "Sum(OrderDate)", "A static value entered manually per customer"], a: 1, e: "Subtracting the customer's most recent order date from today's date (Today() - Max(OrderDate), evaluated per customer) gives a recency metric commonly used to flag churn risk — a standard analyst-level calculation pattern.", t: "Scenario · Hard" },
    { q: "An analyst needs a KPI that shows the percentage of total selected sales contributed by the top 3 customers, to illustrate customer concentration risk.", o: ["This cannot be calculated in Qlik expressions", "Sum of the top-3 customers' sales (via Rank() or a Top-N set analysis condition) divided by Sum(Sales) for the full current selection, expressed as a percentage", "Manually identify the top 3 and hardcode their names permanently", "Count(Distinct CustomerID) instead"], a: 1, e: "Combining a Rank()-based or Top-N set analysis expression for the numerator (top 3 customers' sales) with the overall Sum(Sales) as the denominator produces a dynamic concentration-risk percentage that updates with selections — a more advanced analyst-level set analysis pattern.", t: "Scenario · Hard" },
    { q: "A sheet's chart shows odd results after a user applies selections in a field that has no direct association with the dimension being charted, and the analyst needs to explain why numbers still changed.", o: ["Selections only affect directly associated fields, so this shouldn't be possible", "Explain that Qlik's associative model propagates selections through the entire data model via any chain of associated tables, not just directly linked fields, so an indirectly related selection can still affect the aggregation", "This indicates a corrupted data model", "Numbers changing is always a bug"], a: 1, e: "Qlik's associative engine propagates the effect of a selection across the whole connected data model through chains of association, not just directly linked fields — so a selection in a seemingly unrelated field can still legitimately affect an aggregation elsewhere if there's an indirect association path.", t: "Scenario · Hard" },
    { q: "An analyst wants a single KPI object to switch between showing 'Sales' or 'Profit' based on a dropdown selection the business user controls, without duplicating the object.", o: ["Build two separate KPI objects and hide/show them manually", "Use a variable-driven expression (a dropdown/selection tied to a variable, referenced in the KPI's expression, e.g., $(vSelectedMeasure)) so the same object dynamically switches its calculation", "This requires a separate app per measure", "Only one measure can ever be shown per app"], a: 1, e: "Binding a KPI expression to a variable that a dropdown/input control sets lets a single object dynamically switch what it calculates (e.g., Sales vs Profit) based on user choice, avoiding duplicate objects for each possible metric.", t: "Scenario · Hard" },
    { q: "A business analyst needs a measure showing sales for 'yesterday' compared to the 'same weekday last week' rather than simply the calendar day before, to account for weekly seasonality (e.g., comparing a Monday to the prior Monday).", o: ["Sum({<Date={$(=Today()-1)}>} Sales) is always sufficient for this comparison", "Sum({<Date={$(=Today()-7)}>} Sales) compared against Sum({<Date={$(=Today()-1)}>} Sales), explicitly using a 7-day offset for the weekday-matched comparison rather than a simple prior-day offset", "Compare against the monthly average instead", "This comparison isn't possible in set analysis"], a: 1, e: "To compare against the same weekday in the prior week (accounting for weekly seasonality like weekday vs weekend patterns), the set analysis expression must use a 7-day offset rather than a simple 1-day offset, which would instead compare against a potentially different weekday.", t: "Scenario · Hard" },
  ],
};
